61:       }
62:     };
63: 
64:     boolean match(String component, PathBuilder builder) {
65:       Matcher matcher = pattern.matcher(component);
66:       if (matcher.matches()) {
67:         process(matcher, builder);
68:         return true;
69:       }
70:       return false;
71:     }
