80:   private final ImmutableList<String> tokenNames;
81:   private final Pattern regex;
82: 
83:   private static final Pattern PLACEHOLDER = Pattern.compile("((?:^|/):(\\w+)\\??:([^/])+)|((?:^|/)::([^/])+)|((?:^|/):(\\w+)\\??)");
84: 
85:   protected TokenPathBinder(ImmutableList<String> tokenNames, Pattern regex) {
86:     this.tokenNames = tokenNames;
87:     this.regex = regex;
88:   }
89: 
90:   public static PathBinder build(String path, boolean exact) {
91:     PathBuilder pathBuilder = new DefaultPathBuilder();
92: 
93:     Matcher matchResult = PLACEHOLDER.matcher(path);
94: 
95:     int lastIndex = 0;
96: 
97:     if (matchResult.find()) {
98:       do {
99:         int thisIndex = matchResult.start();
100:         if (thisIndex != lastIndex) {
101:           pathBuilder.literal(path.substring(lastIndex, thisIndex));
102:         }
103:         lastIndex = matchResult.end();
104:         String component = matchResult.group(0);
105:         boolean found = false;
106:         for (TokenType type : TokenType.values()) {
107:           if (type.match(component, pathBuilder)) {
108:             found = true;
109:             break;
110:           }
111:         }
112:         if (!found) {
113:           throw new IllegalArgumentException(String.format("Cannot match path %s (%s)", path, component));
114:         }
115:       } while (matchResult.find());
116:       if (lastIndex < path.length()) {
117:         pathBuilder.literal(path.substring(lastIndex));
118:       }
119:     } else {
120:       pathBuilder.literal(path);
121:     }
122:     return pathBuilder.build(exact);
123:   }
124: 
125:   public PathBinding bind(String path, PathBinding parentBinding) {
126:     if (parentBinding != null) {
127:       path = parentBinding.getPastBinding();
128:     }
129:     Matcher matcher = regex.matcher(path);
130:     if (matcher.matches()) {
131:       MatchResult matchResult = matcher.toMatchResult();
132:       String boundPath = matchResult.group(1);
133:       ImmutableMap.Builder<String, String> paramsBuilder = ImmutableMap.builder();
134:       int i = 2;
135:       for (String name : tokenNames) {
136:         String value = matchResult.group(i++);
137:         if (value != null) {
138:           paramsBuilder.put(name, decodeURIComponent(value));
139:         }
140:       }
141: 
142:       return new DefaultPathBinding(path, boundPath, paramsBuilder.build(), parentBinding);
143:     } else {
144:       return null;
145:     }
146:   }
147: 
148:   private String decodeURIComponent(String s) {
149:     String str;
150:     try {
151:       str = URLDecoder.decode(s.replaceAll("\\+", "%2B"), "UTF-8");
152:     } catch (UnsupportedEncodingException ignored) {
153:       throw new IllegalStateException("UTF-8 decoder should always be available");
154:     }
155:     return str;
156:   }
157: }
