1269:   /**
1270:    * Caches the promised value (or error) and returns it to all subscribers.
1271:    * <p>
1272:    * This method is equivalent to using {@link #cacheResultIf(Predicate)} with a predicate that always returns {@code true}.
1273:    *
1274:    * <pre class="java">{@code
1275:    * import ratpack.exec.Promise;
1276:    * import ratpack.test.exec.ExecHarness;
1277:    *
1278:    * import java.util.concurrent.atomic.AtomicLong;
1279:    *
1280:    * import static org.junit.Assert.assertEquals;
1281:    *
1282:    * public class Example {
1283:    *   public static void main(String... args) throws Exception {
1284:    *     ExecHarness.runSingle(c -> {
1285:    *       AtomicLong counter = new AtomicLong();
1286:    *       Promise<Long> uncached = Promise.async(f -> f.success(counter.getAndIncrement()));
1287:    *
1288:    *       uncached.then(i -> assertEquals(0l, i.longValue()));
1289:    *       uncached.then(i -> assertEquals(1l, i.longValue()));
1290:    *       uncached.then(i -> assertEquals(2l, i.longValue()));
1291:    *
1292:    *       Promise<Long> cached = uncached.cache();
1293:    *
1294:    *       cached.then(i -> assertEquals(3l, i.longValue()));
1295:    *       cached.then(i -> assertEquals(3l, i.longValue()));
1296:    *
1297:    *       uncached.then(i -> assertEquals(4l, i.longValue()));
1298:    *       cached.then(i -> assertEquals(3l, i.longValue()));
1299:    *     });
1300:    *   }
1301:    * }
1302:    * }</pre>
1303:    *
1304:    * <p>
1305:    * If the cached promise fails, the same exception will be returned every time.
1306:    *
1307:    * <pre class="java">{@code
1308:    * import ratpack.exec.Promise;
1309:    * import ratpack.test.exec.ExecHarness;
1310:    *
1311:    * import static org.junit.Assert.assertTrue;
1312:    *
1313:    * public class Example {
1314:    *   public static void main(String... args) throws Exception {
1315:    *     ExecHarness.runSingle(c -> {
1316:    *       Throwable error = new Exception("bang!");
1317:    *       Promise<Object> cached = Promise.error(error).cache();
1318:    *       cached.onError(t -> assertTrue(t == error)).then(i -> assertTrue("not called", false));
1319:    *       cached.onError(t -> assertTrue(t == error)).then(i -> assertTrue("not called", false));
1320:    *       cached.onError(t -> assertTrue(t == error)).then(i -> assertTrue("not called", false));
1321:    *     });
1322:    *   }
1323:    * }
1324:    * }</pre>
1325:    *
1326:    * @return a caching promise
1327:    * @see #cacheIf(Predicate)
1328:    * @see #cacheResultIf(Predicate)
1329:    */
1330:   default Promise<T> cache() {
1331:     return cacheResultIf(Predicate.TRUE);
1332:   }
