896:   /**
897:    * Transforms a failure of the given type (potentially into a value) by applying the given function to it.
898:    * <p>
899:    * This method is similar to {@link #mapError(Function)}, except that it allows async transformation.
900:    *
901:    * @param function the transformation to apply to the promise failure
902:    * @return a promise
903:    * @since 1.3
904:    */
905:   default Promise<T> flatMapError(Function<? super Throwable, ? extends Promise<T>> function) {
906:     return transform(up -> down ->
907:       up.connect(down.onError(throwable -> {
908:         Promise<T> transformed;
909:         try {
910:           transformed = function.apply(throwable);
911:         } catch (Throwable t) {
912:           down.error(t);
913:           return;
914:         }
915:         transformed.connect(down);
916:       }))
917:     );
918:   }
919: 
920:   /**
921:    * Transforms a failure of the given type (potentially into a value) by applying the given function to it.
922:    * <p>
923:    * This method is similar to {@link #mapError(Class, Function)}, except that it allows async transformation.
924:    *
925:    * @param function the transformation to apply to the promise failure
926:    * @return a promise
927:    * @since 1.3
928:    */
929:   default <E extends Throwable> Promise<T> flatMapError(Class<E> type, Function<? super E, ? extends Promise<T>> function) {
930:     return transform(up -> down ->
931:       up.connect(down.onError(throwable -> {
932:         if (type.isInstance(throwable)) {
933:           Promise<T> transformed;
934:           try {
935:             transformed = function.apply(type.cast(throwable));
936:           } catch (Throwable t) {
937:             down.error(t);
938:             return;
939:           }
940:           transformed.connect(down);
941:         } else {
942:           down.error(throwable);
943:         }
944:       }))
945:     );
946:   }
