542:     bindInterceptor(Matchers.any(), Matchers.annotatedWith(Metered.class), injected(new MeteredMethodInterceptor()));
543:     bindInterceptor(Matchers.any(), Matchers.annotatedWith(Timed.class), injected(new TimedMethodInterceptor()));
544:     bindListener(Matchers.any(), injected(new GaugeTypeListener()));
545: 
546:     bind(JmxReporter.class).toProvider(JmxReporterProvider.class).in(SINGLETON);
547:     bind(ConsoleReporter.class).toProvider(ConsoleReporterProvider.class).in(SINGLETON);
548:     bind(CsvReporter.class).toProvider(CsvReporterProvider.class).in(SINGLETON);
549:     bind(MetricRegistryPeriodicPublisher.class).in(SINGLETON);
550:     bind(MetricsBroadcaster.class).in(SINGLETON);
551:     bind(MetricRegistryJsonMapper.class).in(SINGLETON);
552: 
553:     bind(Startup.class);
554:     Multibinder.newSetBinder(binder(), HandlerDecorator.class).addBinding().toProvider(HandlerDecoratorProvider.class);
555:   }
