31: /**
32:  * Static factory methods for creating {@link LaunchConfig} objects using various strategies.
33:  * <p>
34:  * Designed to be used to construct a launch config via a {@link Properties} instance.
35:  * <p>
36:  * Most methods eventually delegate to {@link #createWithBaseDir(ClassLoader, java.io.File, java.util.Properties)}.
37:  * <p>
38:  * When things go wrong, a {@link LaunchException} will be thrown.
39:  */
40: public abstract class LaunchConfigFactory {
41: 
42:   /**
43:    * Value: {@value}.
44:    *
45:    * @see #createFromGlobalProperties(ClassLoader, java.util.Properties, java.util.Properties)
46:    */
47:   public static final String SYSPROP_PREFIX_PROPERTY = "ratpack.syspropPrefix";
48: 
49:   /**
50:    * Value: {@value}.
51:    *
52:    * @see #createFromGlobalProperties(ClassLoader, java.util.Properties, java.util.Properties)
53:    */
54:   public static final String SYSPROP_PREFIX_DEFAULT = "ratpack.";
55: 
56:   public static final String CONFIG_RESOURCE_PROPERTY = "configResource";
57:   public static final String CONFIG_RESOURCE_DEFAULT = "ratpack.properties";
58: 
59:   private LaunchConfigFactory() {
60:   }
61: 
62:   /**
63:    * Delegates to {@link #createFromGlobalProperties(ClassLoader, String, java.util.Properties, java.util.Properties)}, extracting the “propertyPrefix” from the “globalProperties”.
64:    * <p>
65:    * Determines the “propertyPrefix” value and delegates to {@link #createFromGlobalProperties(ClassLoader, String, java.util.Properties, java.util.Properties)}.
66:    * The value is determined by: {@code globalProperties.getProperty(SYSPROP_PREFIX_PROPERTY, SYSPROP_PREFIX_DEFAULT)}
67:    *
68:    * @param classLoader The classloader to use to find the properties file.
69:    * @param globalProperties The environmental (override) properties
70:    * @param defaultProperties The default properties to use when a property is omitted
71:    * @return A launch config
72:    */
73:   public static LaunchConfig createFromGlobalProperties(ClassLoader classLoader, Properties globalProperties, Properties defaultProperties) {
74:     String propertyPrefix = globalProperties.getProperty(SYSPROP_PREFIX_PROPERTY, SYSPROP_PREFIX_DEFAULT);
75:     return createFromGlobalProperties(classLoader, propertyPrefix, globalProperties, defaultProperties);
76:   }
77: 
78:   /**
79:    * Delegates to {@link #createFromProperties(ClassLoader, java.util.Properties, java.util.Properties)} after extracting the “prefixed” properties from the global properties.
80:    * <p>
81:    * The properties of {@code globalProperties} that begin with {@code propertyPrefix} are extracted into a new property set,
82:    * with the property names having the prefix removed.
83:    * This becomes the {@code overrideProperties} for the delegation to {@link #createFromProperties(ClassLoader, java.util.Properties, java.util.Properties)}.
84:    *
85:    * @param classLoader The classloader to use to find the properties file
86:    * @param propertyPrefix The prefix of properties in {@code globalProperties} that should be extracted to form the override properties
87:    * @param globalProperties The environmental (override) properties
88:    * @param defaultProperties The default properties to use when a property is omitted
89:    * @return A launch config
90:    */
91:   public static LaunchConfig createFromGlobalProperties(ClassLoader classLoader, String propertyPrefix, Properties globalProperties, Properties defaultProperties) {
92:     Properties deprefixed = new Properties();
93:     extractProperties(propertyPrefix, globalProperties, deprefixed);
94:     return createFromProperties(classLoader, deprefixed, defaultProperties);
95:   }
96: 
97:   /**
98:    * Extracts the properties prefixed with {@value #SYSPROP_PREFIX_DEFAULT} from the system properties, without the prefix.
99:    *
100:    * @return the properties prefixed with {@value #SYSPROP_PREFIX_DEFAULT} from the system properties, without the prefix.
101:    */
102:   public static Properties getDefaultPrefixedProperties() {
103:     Properties deprefixed = new Properties();
104:     extractProperties(SYSPROP_PREFIX_DEFAULT, System.getProperties(), deprefixed);
105:     return deprefixed;
106:   }
107: 
108:   private static void extractProperties(String propertyPrefix, Properties properties, Map<? super String, ? super String> destination) {
109:     for (String propertyName : properties.stringPropertyNames()) {
110:       if (propertyName.startsWith(propertyPrefix)) {
111:         destination.put(propertyName.substring(propertyPrefix.length()), properties.getProperty(propertyName));
112:       }
113:     }
114:   }
115: 
116:   /**
117:    * Delegates to {@link #createFromFile(ClassLoader, java.io.File, java.io.File, java.util.Properties, java.util.Properties)}, after trying to find the config properties file.
118:    * <p>
119:    * The {@code overrideProperties} are queried for the {@link #CONFIG_RESOURCE_PROPERTY} (defaulting to {@link #CONFIG_RESOURCE_DEFAULT}).
120:    * The {@code classLoader} is asked for the classpath resource with this name.
121:    * <p>
122:    * If the resource DOES NOT exist, {@link #createFromFile(ClassLoader, java.io.File, java.io.File, java.util.Properties, java.util.Properties)} is called with
123:    * the current JVM user dir as the {@code baseDir} and {@code null} as the {@code configFile}.
124:    * <p>
125:    * If the resource DOES exist, {@link #createFromFile(ClassLoader, java.io.File, java.io.File, java.util.Properties, java.util.Properties)} is called with
126:    * that file resource as the {@code configFile}, and its parent directory as the {@code baseDir}.
127:    *
128:    * @param classLoader The classloader to use to find the properties file
129:    * @param overrideProperties The properties that provide the path to the config file resource, and any overrides
130:    * @param defaultProperties The default properties to use when a property is omitted
131:    * @return A launch config
132:    */
133:   public static LaunchConfig createFromProperties(ClassLoader classLoader, Properties overrideProperties, Properties defaultProperties) {
134:     String configResourceValue = overrideProperties.getProperty(CONFIG_RESOURCE_PROPERTY, CONFIG_RESOURCE_DEFAULT);
135:     File configFile = new File(CONFIG_RESOURCE_DEFAULT);
136:     if (!configFile.exists()) {
137:       URL configResourceUrl = classLoader.getResource(configResourceValue);
138:       if (configResourceUrl == null) {
139:         return createFromFile(classLoader, new File(System.getProperty("user.dir")), null, overrideProperties, defaultProperties);
140:       }
141: 
142:       try {
143:         URI uri = configResourceUrl.toURI();
144:         configFile = new File(uri);
145:       } catch (Exception e) {
146:         throw new LaunchException("Could not get file for config file resource '" + configResourceUrl + "'", e);
147:       }
148:     }
149: 
150:     return createFromFile(classLoader, configFile.getParentFile(), configFile, overrideProperties, defaultProperties);
151:   }
152: 
153:   /**
154:    * Delegates to {@link #createWithBaseDir(ClassLoader, java.io.File, java.util.Properties)}, after merging the properties from {@code configFile} and {@code overrideProperties}.
155:    * <p>
156:    * If {@code configFile} exists and is not null, it is read as a properties file.
157:    * It is then merged with {@code defaultProperties} & {@code overrideProperties}.
158:    * The default properties are overridden by values in the properties file, while the override properties will override these properties.
159:    *
160:    * @param classLoader The classloader to use to find the properties file
161:    * @param baseDir The {@link org.ratpackframework.launch.LaunchConfig#getBaseDir()} of the eventual launch config
162:    * @param configFile The configuration properties file
163:    * @param overrideProperties The properties that override default and file properties
164:    * @param defaultProperties The default properties to use when a property is omitted
165:    * @return a launch config
166:    */
167:   public static LaunchConfig createFromFile(ClassLoader classLoader, File baseDir, @Nullable File configFile, Properties overrideProperties, Properties defaultProperties) {
168:     Properties fileProperties = new Properties(defaultProperties);
169:     if (configFile != null && configFile.exists()) {
170:       try (InputStream inputStream = new FileInputStream(configFile)) {
171:         fileProperties.load(inputStream);
172:       } catch (Exception e) {
173:         throw new LaunchException("Could not read config file '" + configFile + "'", e);
174:       }
175:     }
176: 
177:     fileProperties.putAll(overrideProperties);
178: 
179:     return createWithBaseDir(classLoader, baseDir, fileProperties);
180:   }
181: 
182:   /**
183:    * Constructs a launch config, based on the given properties.
184:    * <p>
185:    * See {@link Property} for details on the valid properties.
186:    *
187:    * @param classLoader The classloader used to load the {@link Property#HANDLER_FACTORY} class
188:    * @param baseDir The {@link org.ratpackframework.launch.LaunchConfig#getBaseDir()} value
189:    * @param properties The values to use to construct the launch config
190:    * @return A launch config
191:    */
192:   public static LaunchConfig createWithBaseDir(ClassLoader classLoader, File baseDir, Properties properties) {
193:     try {
194:       String handlerFactoryClassName = properties.getProperty(Property.HANDLER_FACTORY);
195:       if (handlerFactoryClassName == null) {
196:         throw new LaunchException("No handler factory class specified (config property: " + Property.HANDLER_FACTORY + ")");
197:       }
198: 
199:       Class<?> untypedClass = classLoader.loadClass(handlerFactoryClassName);
200:       if (!HandlerFactory.class.isAssignableFrom(untypedClass)) {
201:         throw new LaunchException("Given handler factory class '" + handlerFactoryClassName + "' does not implement '" + HandlerFactory.class.getName());
202:       }
203: 
204:       @SuppressWarnings("unchecked") Class<HandlerFactory> handlerFactoryClass = (Class<HandlerFactory>) untypedClass;
205: 
206:       int port = Integer.valueOf(properties.getProperty(Property.PORT, new Integer(LaunchConfig.DEFAULT_PORT).toString()));
207: 
208:       InetAddress address = null;
209:       String addressString = properties.getProperty(Property.ADDRESS);
210: 
211:       if (addressString != null) {
212:         try {
213:           address = InetAddress.getByName(addressString);
214:         } catch (UnknownHostException e) {
215:           throw new IllegalStateException("Failed to resolve requested bind address: " + addressString, e);
216:         }
217:       }
218: 
219:       URI uri = null;
220:       String uriString = properties.getProperty(Property.URI);
221: 
222:       if (uriString != null) {
223:         try {
224:           uri = new URI(uriString);
225:         } catch (URISyntaxException ex) {
226:           throw new IllegalStateException("Failed to create URI from: " + uriString, ex);
227:         }
228:       }
229: 
230:       boolean reloadable = Boolean.parseBoolean(properties.getProperty(Property.RELOADABLE, "false"));
231:       int mainThreads = Integer.valueOf(properties.getProperty(Property.MAIN_THREADS, "0"));
232: 
233:       String indexFilesValue = properties.getProperty(Property.INDEX_FILES, "");
234:       ImmutableList.Builder<String> trimmed = ImmutableList.builder();
235:       for (String value : indexFilesValue.split(",")) {
236:         value = value.trim();
237:         if (!value.isEmpty()) {
238:           trimmed.add(value);
239:         }
240:       }
241:       List<String> indexFiles = trimmed.build();
242: 
243:       Map<String, String> otherProperties = new HashMap<>();
244:       extractProperties("other.", properties, otherProperties);
245: 
246:       HandlerFactory handlerFactory;
247:       try {
248:         handlerFactory = handlerFactoryClass.newInstance();
249:       } catch (Exception e) {
250:         throw new LaunchException("Could not instantiate handler factory: " + handlerFactoryClass.getName(), e);
251:       }
252: 
253:       return LaunchConfigBuilder.baseDir(baseDir)
254:         .port(port)
255:         .address(address)
256:         .publicAddress(uri)
257:         .reloadable(reloadable)
258:         .mainThreads(mainThreads)
259:         .indexFiles(indexFiles)
260:         .other(otherProperties)
261:         .build(handlerFactory);
262: 
263:     } catch (Exception e) {
264:       if (e instanceof LaunchException) {
265:         throw (LaunchException) e;
266:       } else {
267:         throw new LaunchException("Failed to create launch config with properties: " + properties.toString(), e);
268:       }
269:     }
270:   }
271: 
272:   /**
