65:    *
66:    * @param dir the base dir root
67:    * @return a new embedded base dir
68:    */
69:   static EmbeddedBaseDir dir(File dir) {
70:     return new PathEmbeddedBaseDir(dir);
71:   }
72: 
73:   /**
74:    * Creates a new base dir which is actually a jar created within the JVM's assigned temp dir.
75:    * <p>
76:    * This is typically used when testing Ratpack extensions to verify that they don't assume they are
