78:    *
79:    * @return a new embedded base dir
80:    */
81:   static EmbeddedBaseDir tmpJar() {
82:     return jar(Exceptions.uncheck(() -> File.createTempFile("ratpack", ".jar")));
83:   }
84: 
85:   /**
86:    * Creates a new base dir which is actually a jar at the given location.
87:    * <p>
88:    * This is typically used when testing Ratpack extensions to verify that they don't assume they are
89:    * running from the default file system.
90:    * <p>
