138:   public static void start(EventLoop eventLoop, ExecControl execControl, final RequestConstants requestConstants, Registry registry, Handler[] handlers, Action<? super Execution> onComplete) {
139:     ChainIndex index = new ChainIndex(handlers, registry, true);
140:     requestConstants.indexes.push(index);
141: 
142:     DefaultContext context = new DefaultContext(requestConstants);
143:     requestConstants.context = context;
144: 
145:     execControl.exec()
146:       .onError(throwable -> requestConstants.context.error(throwable instanceof HandlerException ? throwable.getCause() : throwable))
147:       .onComplete(onComplete)
