142:     this.templatesCacheSize = templatesCacheable;
143:   }
144: 
145:   public Long getCacheTTLMs() {
146:     return cacheTTLMs;
147:   }
148: 
149:   public void setCacheTTLMs(Long cacheTTLMs) {
150:     this.cacheTTLMs = cacheTTLMs;
151:   }
152: 
153:   @Override
154:   protected void configure() {
155:     bind(ThymeleafTemplateRenderer.class).in(Singleton.class);
156:     bind(ITemplateResolver.class).to(FileTemplateResolver.class).in(Singleton.class);
157:   }
158: 
159:   @SuppressWarnings("UnusedDeclaration")
160:   @Provides
161:   FileTemplateResolver provideITemplateResolver(LaunchConfig launchConfig) {
162:     final FileTemplateResolver templateResolver = new FileTemplateResolver();
163: 
164:     String mode = templatesMode == null ? launchConfig.getOther("thymeleaf.templatesMode", DEFAULT_TEMPLATE_MODE) : templatesMode;
165:     String prefix = templatesPrefix == null ? launchConfig.getOther("thymeleaf.templatesPrefix", DEFAULT_TEMPLATE_PREFIX) : templatesPrefix;
166:     String suffix = templatesSuffix == null ? launchConfig.getOther("thymeleaf.templatesSuffix", DEFAULT_TEMPLATE_SUFFIX) : templatesSuffix;
167:     Boolean cacheable = templatesCacheSize == null ? Boolean.valueOf(launchConfig.getOther("thymeleaf.templatesCacheable", "true")) : templatesCacheSize;
168:     Long cacheTTL = cacheTTLMs == null ? Long.valueOf(launchConfig.getOther("thymeleaf.cacheTTLMs", "0")) : cacheTTLMs;
169: 
170:     templateResolver.setTemplateMode(mode);
171: 
172:     File finalPrefixPathFile = new File(launchConfig.getBaseDir(), prefix);
173:     String path = finalPrefixPathFile.getAbsolutePath();
174:     if (path.charAt(path.length() - 1) != File.separatorChar) {
175:       path += File.separator;
176:     }
177:     templateResolver.setPrefix(path);
178: 
179:     if (suffix.equalsIgnoreCase("")) {
180:       suffix = DEFAULT_TEMPLATE_SUFFIX;
181:     }
182:     templateResolver.setSuffix(suffix);
183: 
184:     templateResolver.setCacheable(cacheable != null && cacheable);
185:     templateResolver.setCacheTTLMs(cacheTTL != null && cacheTTL > 0 ? cacheTTL : null);
186: 
187:     return templateResolver;
188:   }
189: 
