191:   @Provides
192:   @Singleton
193:   TemplateEngine provideTemplateEngine(ITemplateResolver templateResolver) {
194:     final TemplateEngine templateEngine = new TemplateEngine();
195:     templateEngine.setTemplateResolver(templateResolver);
196:     return templateEngine;
197:   }
198: }

