52:               bufferedSubscribers.add(s);
53:               tryUpstreamSubscribe();
54:             }
55: 
56:             @Override
57:             public void cancel() {
58:               // buffer will deal with cancelling this subscription if the downstream subscriber cancels or throws an exception.
59:               // The downstream subscriber will be "unsubscribed" from this publisher.
60:               bufferedSubscribers.remove(s);
61:             }
62:           });
63:         }
64:       }).subscribe(downStreamSubscriber);
